import { PieArcDatum, ProvidedProps } from '@visx/shape/lib/shapes/Pie';
import React from 'react';

import { PieChartLabel } from './PieChartLabel.js';
import { INACTIVE_FILL_OPACITY_PIE_CHART } from '../../core/constants.js';
import { useFormatter } from '../context/FormatterContext.js';
import { useLabels } from '../context/LabelsContext.js';
import { useSliceHandlers } from '../hooks/useSliceHandlers.js';
import { InternalSliceData } from '../types/internal/pie-chart.js';

export interface PieSliceProps {
  sliceId: string;
  arc: PieArcDatum<{ category: string; value: number } & InternalSliceData>;
  data: InternalSliceData;
  path: ProvidedProps<InternalSliceData>['path'];
}

export const PieChartSlice = (props: PieSliceProps) => {
  const { sliceId, arc, data, path } = props;
  const arcPath = path(arc);
  const { hidden } = useLabels();
  const formatter = useFormatter();
  const { onMouseClickHandler, onMouseEnterHandler, onMouseLeaveHandler } =
    useSliceHandlers(sliceId, data, formatter);

  return (
    <g
      onMouseEnter={onMouseEnterHandler}
      onClick={onMouseClickHandler}
      onMouseLeave={onMouseLeaveHandler}
    >
      {!hidden && <PieChartLabel {...props} />}
      <path
        d={arcPath || ''}
        fill={data.color.Default}
        opacity={data.highlighted ? 0.85 : INACTIVE_FILL_OPACITY_PIE_CHART}
      />
    </g>
  );
};
PieChartSlice['displayName'] = 'PieChartSlice';
